<section class="poste-hero"><span class="poste-hero-label">E-Tounsi · Municipalité</span><h1 class="page-title">Mes demandes municipales</h1><p>Consultez l’avancement de vos demandes, paiements et notifications liés à votre compte.</p><a class="btn-custom btn-custom-primary" href="index.php?page=municipalite-services">Nouvelle démarche</a></section>
<?php if($notifications): ?><section class="content-panel mt-4"><h2 class="h5">Notifications</h2><?php foreach($notifications as $n): ?><article class="border-bottom py-2"><strong><?= e($n['titre']) ?></strong><p class="mb-1"><?= e($n['message']) ?></p><small class="text-secondary"><?= e(date('d/m/Y H:i',strtotime($n['cree_le']))) ?></small></article><?php endforeach; ?></section><?php endif; ?>
<?php if(!$demandes): ?><p class="content-panel mt-4">Aucune demande enregistrée pour votre compte.</p><?php else: ?><div class="row g-3 mt-1">
<?php foreach($demandes as $d): $details=json_decode((string)$d['precision_demande'],true)?:[]; ?><div class="col-12"><article class="content-panel">
<div class="d-flex justify-content-between flex-wrap gap-2"><div><p class="eyebrow mb-1">Référence DM-<?= str_pad((string)$d['id_demande'],5,'0',STR_PAD_LEFT) ?></p><h2 class="h5"><?= e($d['libelle']) ?></h2></div><span class="badge text-bg-<?= $d['statut']==='document_pret'?'success':($d['statut']==='rejetee'?'danger':'primary') ?>"><?= e(str_replace('_',' ',ucfirst($d['statut']))) ?></span></div>
<p class="mb-2">Déposée le <?= e(date('d/m/Y H:i',strtotime($d['date_depot']))) ?> · <?= $d['mode_traitement']==='rendez_vous'?'Rendez-vous':'Retrait au guichet' ?><?php if($d['date_souhaitee']): ?> · <?= e($d['delegation']) ?>, <?= e($d['gouvernorat']) ?> · <?= e(date('d/m/Y H:i',strtotime($d['date_souhaitee']))) ?> (<?= e($d['statut_rdv']??'en attente') ?>)<?php endif; ?></p>
<p><strong>Frais :</strong> <?= e(number_format((float)$d['frais'],3,',',' ')) ?> DT · <strong>Paiement :</strong> <?= e($d['paiement_statut']??'sans frais') ?></p>
<details><summary>Voir les informations déclarées</summary><dl class="row mt-3"><?php foreach($details as $key=>$value): if($key==='telephone_contact'||$value==='')continue; ?><dt class="col-sm-4"><?= e(ucfirst(str_replace('_',' ',$key))) ?></dt><dd class="col-sm-8"><?= e(is_scalar($value)?(string)$value:'') ?></dd><?php endforeach; ?></dl></details>
<div class="d-flex flex-wrap gap-2 mt-3"><a class="button button-light" href="index.php?page=municipalite-recu&amp;id=<?= (int)$d['id_demande'] ?>">Voir le récépissé / imprimer</a>
<?php if($d['paiement_statut']==='en_attente'&&$carteActive): ?><form method="post" action="index.php?page=municipalite-payer"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id_demande" value="<?= (int)$d['id_demande'] ?>"><button class="button button-dark" type="submit">Payer par carte bancaire</button></form><?php endif; ?>
<?php if($d['paiement_statut']==='en_attente'&&$demoActive): ?><form method="post" action="index.php?page=municipalite-paiement-demo"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id_demande" value="<?= (int)$d['id_demande'] ?>"><button class="button button-light" type="submit">Tester le paiement (démo)</button></form><?php endif; ?>
</div></article></div><?php endforeach; ?></div><?php endif; ?>
